mapper.select:
SELECT DISTINCT ch.channel_code as channelCode, dataTable.order_code, (case when length(COALESCE(tdr.channel_name, '')) = 0 then ch.channel_name else tdr.channel_name end) as channelName, (case when length(COALESCE(tdr.device_name, '')) = 0 then dataTable.device_name else tdr.device_name end) as deviceName, dataTable.device_code, COALESCE(vac.algorithmCount, 0) AS algorithmCount, dataTable.accept_node AS acceptNode FROM (SELECT ord.device_code,ord.tenant_id as tenant_id, m.device_name, m.province_id as province_code, m.city_id as city_code ,m.county_id as county_code,ord.delete_flag,ord.industry_code,m.town_code,ord.order_code, ord.accept_node AS accept_node FROM vm_order_devices ord LEFT JOIN vm_device_info_t m on m.device_code = ord.device_code where m.delete_flag = '0' and ord.ord_status in (0, 1, 2) ) dataTable LEFT JOIN vm_channel_info_t ch on ch.device_code = dataTable.device_code LEFT JOIN ( SELECT config_id,device_code,channel_code,tenant_id,industry_code,algorithm_code,'1' AS task_type FROM vm_algorithm_config WHERE delete_flag = 0 AND industry_code = #{param.industryCode} AND tenant_id = #{param.tenantId} UNION ALL SELECT id AS config_id,device_code,channel_code,tenant_id,industry_code,alarm_type AS algorithm_code,'2' AS task_type FROM vm_algorithm_give_config WHERE delete_flag = 0 AND industry_code = #{param.industryCode} AND tenant_id = #{param.tenantId} ) cf ON ch.channel_code=cf.channel_code and cf.device_code = dataTable.device_code and dataTable.tenant_id=cf.tenant_id and cf.industry_code = dataTable.industry_code LEFT JOIN ( select count(*) AS algorithmCount, a.device_code AS device_code,a.channel_code AS channelCode, a.tenant_id AS tenantId from ( SELECT config_id,device_code,channel_code,tenant_id FROM vm_algorithm_config WHERE delete_flag = 0 AND industry_code = #{param.industryCode} AND tenant_id = #{param.tenantId} UNION ALL SELECT id AS config_id,device_code,channel_code,tenant_id FROM vm_algorithm_give_config WHERE delete_flag = 0 AND industry_code = #{param.industryCode} AND tenant_id = #{param.tenantId}) a group by a.device_code,a.channel_code,a.tenant_id ) vac ON vac.channelCode = ch.channel_code AND vac.device_code = ch.device_code AND vac.tenantId = dataTable.tenant_id LEFT JOIN vm_tenant_device_channel_rel_t tdr on tdr.device_code = dataTable.device_code and tdr.tenant_id = dataTable.tenant_id and tdr.channel_code = ch.channel_code and tdr.industry_code = dataTable.industry_code
LEFT JOIN vm_organ_device_rel_t odr ON dataTable.device_code = odr.device_code AND odr.device_type = 4
LEFT JOIN (SELECT l.`label_id`, l.`label_name`, l.`tenant_id`, rel.`device_code` FROM vm_device_labels_rel rel INNER JOIN vm_tenant_label_config l USING (label_id)) lab ON lab.tenant_id = dataTable.tenant_id AND lab.device_code = dataTable.device_code
LEFT JOIN vm_device_diy_tree_node_t diy on dataTable.device_code = diy.device_code
WHERE dataTable.delete_flag = '0' AND ch.delete_flag = '0' ${param.dataScope}
AND odr.dept_id LIKE CONCAT(#{param.orgIdCode},'%')
AND odr.dept_id in
#{id}
AND lab.label_id = #{param.labelId}
AND lab.label_id in
#{id}
AND diy.tree_id = #{param.treeId} AND diy.node_code like concat(#{param.nodeCode},'-%')
AND dataTable.industry_code = #{param.industryCode}
AND dataTable.province_code = #{param.provinceId}
AND dataTable.city_code = #{param.cityId}
AND dataTable.county_code = #{param.countryId}
AND dataTable.town_code = #{param.townCode}
AND dataTable.device_code like concat('%',#{param.deviceCode},'%')
AND ch.channel_code like concat('%',#{param.channelCode},'%')
AND dataTable.tenant_id like concat('%',#{param.tenantId},'%')
and cf.algorithm_code=#{param.algorithmCode}
and cf.task_type=#{param.taskType}
AND cf.algorithm_code in
#{id}
GROUP by ch.channel_code
having algorithmCount>0
having algorithmCount=0
ORDER BY dataTable.province_code, dataTable.city_code, dataTable.county_code, dataTable.town_code, dataTable.device_code, ch.channel_code
ORDER BY odr.dept_id, dataTable.device_code, ch.channel_code
ORDER BY lab.label_id, dataTable.device_code, ch.channel_code

select config_id as configId, algorithm_code as algorithmCode, algorithm_name as algorithmName, points, img, task_id as taskId, status, pos_type as posType, algorithm_status as algorithmStatus, extend_json_algo extendJsonAlgo from vm_algorithm_config where delete_flag = '0'
AND industry_code = #{industryCode}
and config_id in
#{item.configId}

SELECT distinct ac.config_id, ac.device_code, ac.channel_code, ac.pos_type, ac.tenant_id, ac.create_time, m.longitude,m.latitude,m.visual_radius,ac.algorithm_code,ac.algorithm_name, ac.creator,ac.modifier, case when ac.preset_id = '0' then null else ac.preset_id end AS presetId, ac.oil_gas_pipelines,ac.update_time, ac.points,ac.img,ac.task_id,ac.status,ac.algorithm_status,ac.tenant_id,'1' AS task_type,ac.thresh, COALESCE(vp.preset_name, ac.preset_name) AS presetName,ac.model_config,ac.trip_thread,ac.analysis_period, (case when length(COALESCE(tdr.channel_name, '')) = 0 then ch.channel_name else tdr.channel_name end) as channelName, (case when length(COALESCE(tdr.device_name, '')) = 0 then m.device_name else tdr.device_name end) as deviceName, us1.NICK_NAME AS creatorName, us2.NICK_NAME AS modifierName, ac.time_interval, ac.time_interval_unit, ac.text_labels, ac.is_linkage_algorithm, ac.linkage_algorithm as linkageAlgorithmInfo, CONVERT(ac.extend_json_algo, CHAR) as extendJsonAlgo ,CASE WHEN ac.scene_code IS NULL THEN 0 ELSE 1 END AS modelType ,ac.scene_code ,ac.alarmInterval FROM vm_algorithm_config ac LEFT JOIN vm_video_preset vp ON vp.preset_id = ac.preset_id and vp.device_code = ac.device_code LEFT JOIN vm_device_info_t m ON m.device_code = ac.device_code LEFT JOIN vm_channel_info_t ch ON ch.channel_code = ac.channel_code LEFT JOIN vm_tenant_device_channel_rel_t tdr on tdr.device_code = m.device_code and tdr.channel_code = ch.channel_code and tdr.tenant_id = ac.tenant_id and tdr.industry_code = ac.industry_code LEFT JOIN sys_user us1 on us1.USER_NAME = ac.creator AND us1.DEL_FLAG = '0' LEFT JOIN sys_user us2 on us2.USER_NAME = ac.modifier AND us2.DEL_FLAG = '0' WHERE ch.delete_flag = 0 and m.delete_flag = 0
AND ac.config_id = #{configId}
AND ac.config_id in
#{id}

SELECT distinct ac.config_id,ac.preset_id,pre.preset_name,ac.device_code,ac.channel_code, (case when length(COALESCE(tdr.channel_name, '')) = 0 then ch.channel_name else tdr.channel_name end) as channelName, (case when length(COALESCE(tdr.device_name, '')) = 0 then de.device_name else tdr.device_name end) as deviceName, ac.algorithm_code,ac.algorithm_name,ac.points,ac.img,ac.task_id,ac.status,ac.create_time,ac.update_time, ac.algorithm_status,ac.pos_type,ac.tenant_id,ac.creator,ac.modifier,ac.task_type,ac.model_config, ac.trip_thread,ac.oil_gas_pipelines,second_switch,backendAlgoName,ac.text_labels, ac.points_lon_lat AS pointsLonLat, ac.trip_thread_lon_lat AS tripThreadLonLat, ac.oil_gas_pipelines_lon_lat AS oilGasPipelinesLonLat, ac.text_labels_lon_lat AS textLabelsLonLat FROM ( SELECT config_id,device_code,channel_code,tenant_id,industry_code,algorithm_code,algorithm_name, STATUS,'1' AS task_type,pos_type,preset_id,points,img,task_id,algorithm_status,thresh,model_config, trip_thread,create_time,update_time,creator,modifier,delete_flag,oil_gas_pipelines, '' AS second_switch, '' AS backendAlgoName,text_labels, points_lon_lat, trip_thread_lon_lat, oil_gas_pipelines_lon_lat, text_labels_lon_lat FROM vm_algorithm_config WHERE delete_flag = 0 AND industry_code = #{industryCode} AND tenant_id = #{tenantId}
AND pos_type = #{posType}
AND device_code = #{deviceCode}
AND channel_code = #{channelCode}
AND algorithm_code not in
#{item}
and (device_code, channel_code) in
(#{item.deviceCode}, #{item.channelCode})
UNION ALL SELECT id AS config_id,device_code,channel_code,tenant_id,industry_code,alarm_type AS algorithm_code, alarm_type_name AS algorithm_name,STATUS,'2' AS task_type,NULL AS pos_type,NULL AS preset_id,'' AS points, '' AS img,'' AS task_id,sync_status AS algorithm_status,NULL AS thresh,'' AS model_config,'' AS trip_thread, create_time,update_time,creator,modifier,delete_flag,'' AS oil_gas_pipelines,second_switch, algorithm_name AS backendAlgoName,NULL AS text_labels, NULL AS points_lon_lat, NULL AS trip_thread_lon_lat, NULL AS oil_gas_pipelines_lon_lat, NULL AS text_labels_lon_lat FROM vm_algorithm_give_config WHERE delete_flag = 0 AND industry_code = #{industryCode} AND tenant_id = #{tenantId}
AND device_code = #{deviceCode}
AND channel_code = #{channelCode}
and (device_code, channel_code) in
(#{item.deviceCode}, #{item.channelCode})
) ac LEFT JOIN vm_device_info_t de on ac.device_code = de.device_code and de.delete_flag = 0 LEFT JOIN vm_channel_info_t ch on ac.channel_code = ch.channel_code and ch.delete_flag = 0 LEFT JOIN vm_video_preset pre on pre.preset_id = ac.preset_id and ac.device_code = pre.device_code and pre.delete_flag = 0 LEFT JOIN vm_tenant_device_channel_rel_t tdr on tdr.device_code = de.device_code and tdr.tenant_id = ac.tenant_id and tdr.channel_code = ch.channel_code and tdr.industry_code = ac.industry_code and tdr.delete_flag = 0 WHERE 1=1
AND ac.algorithm_code=#{algorithmCode}
AND ac.config_id = #{configId}
AND ac.task_type=#{taskType}
AND ac.status=#{status}
AND ac.algorithm_code in
#{id}
order by ac.create_time
desc
order by ac.update_time
desc
ORDER BY ac.create_time DESC

SELECT DISTINCT ch.channel_code as channelCode,m.longitude,m.latitude,m.visual_radius, ord.device_code as deviceCode, (case when length(COALESCE(tdr.channel_name, '')) = 0 then ch.channel_name else tdr.channel_name end ) as channelName, (case when length(COALESCE(tdr.device_name, '')) = 0 then m.device_name else tdr.device_name end ) as deviceName, ord.tenant_id as tenantId, ord.industry_code as industryCode FROM vm_order_devices ord LEFT JOIN vm_device_info_t m on m.device_code = ord.device_code LEFT JOIN vm_channel_info_t ch on ch.device_code = ord.device_code LEFT JOIN vm_tenant_device_channel_rel_t tdr on tdr.device_code = m.device_code and tdr.tenant_id = ord.tenant_id and tdr.channel_code = ch.channel_code and tdr.industry_code = ord.industry_code WHERE ord.tenant_id = #{tenantId} and ord.delete_flag = '0' and ord.ord_status in (0, 1, 2)
AND m.province_id = #{provinceId}
AND ord.industry_code = #{industryCode}
AND m.city_id = #{cityId}
AND m.county_id = #{countryId}
AND m.device_code = #{deviceCode}
AND ch.channel_code = #{channelCode}
AND exists not exists ( select 1 from vm_algorithm_config ac where ac.device_code = m.device_code and ac.channel_code = ch.channel_code and ac.tenant_id = ord.tenant_id )
AND exists ( select 1 from vm_algorithm_config ac where ac.device_code = m.device_code and ac.channel_code = ch.channel_code and ac.tenant_id = ord.tenant_id and ac.algorithm_code = #{algorithmCode} and ac.delete_flag = '0' )
ORDER BY m.province_id,m.city_id, m.county_id,m.device_code,ch.channel_code

select a.AREA_CODE from sys_area a where a.AREA_CODE IN

    #{item.townCode}

and a.DEL_FLAG = '0'

WITH rank_values AS ( SELECT t.channelCode, t.channelName, t.algorithmCount, ROW_NUMBER() OVER ( ORDER BY t.algorithmCount DESC ) AS `rank` FROM ( SELECT t2.channel_code channelCode, t2.channel_name channelName, t2.algorithmCount FROM vm_order_devices t1 left join ( select count(*) AS algorithmCount, channel_code,channel_name, tenant_id ,algorithm_code, device_code, delete_flag,industry_code from vm_algorithm_config a where delete_flag = '0'
AND status = #{status}
group by channel_code,tenant_id) t2 ON t1.device_code = t2.device_code AND t1.tenant_id = t2.tenant_id AND t1.industry_code = t2.industry_code WHERE t1.delete_flag = 0 AND t2.delete_flag = 0 AND t1.ord_status in (0, 1, 2) ${dataScope} GROUP BY t2.channel_code ) t ) SELECT * FROM rank_values
WHERE `rank` <= #{topN}

