mapper.select:
SELECT DISTINCT dataTable.device_code, chan.channel_code, COUNT(*) AS orderAlgoCount FROM vm_order_devices dataTable LEFT JOIN vm_order_algorithms oral on oral.tenant_id = dataTable.tenant_id AND oral.order_code = dataTable.order_code AND oral.package_code = dataTable.package_code LEFT JOIN vm_channel_info_t chan ON dataTable.device_code = chan.device_code LEFT JOIN vm_algorithm_info_t b on b.algorithm_code = oral.algorithm_code and b.delete_flag = '0' WHERE dataTable.delete_flag = 0 AND dataTable.ord_status IN (0, 1, 2) AND oral.delete_flag = 0 AND oral.ord_status IN (0, 1, 2) AND dataTable.industry_code = #{industryCode} AND b.app_scenarios = '1' ${dataScope}
AND chan.channel_code in
#{labelIdItem}
AND ( NOT EXISTS (SELECT 1 FROM vm_order_algorithm_config oac WHERE oac.order_code = dataTable.order_code AND oac.delete_flag = 0 AND oac.algorithm_type = 1) OR EXISTS (SELECT 1 FROM vm_order_algorithm_config oac WHERE oac.order_code = dataTable.order_code AND oac.device_code = dataTable.device_code AND oac.algorithm_code = oral.algorithm_code AND oac.delete_flag = 0 AND oac.algorithm_type = 1) ) GROUP BY dataTable.device_code, chan.channel_code ORDER BY dataTable.device_code,chan.channel_code

SELECT DISTINCT mm.device_code, mm.channel_code, COUNT(*) AS algoConfigCount FROM (SELECT DISTINCT tt.device_code, tt.channel_code, tt.algorithm_code, tt.tenant_id, tt.industry_code,tt.accept_node FROM vm_algorithm_config tt WHERE tt.delete_flag = 0 AND tt.industry_code = #{industryCode} AND tt.tenant_id = #{tenantId}) mm LEFT JOIN vm_order_devices ord ON mm.device_code = ord.device_code AND mm.tenant_id = ord.tenant_id AND mm.industry_code = ord.industry_code AND mm.accept_node = ord.accept_node LEFT JOIN vm_order_algorithms oral ON mm.algorithm_code = oral.algorithm_code AND mm.tenant_id = oral.tenant_id AND mm.industry_code = oral.industry_code AND oral.order_code = ord.order_code AND oral.package_code = ord.package_code LEFT JOIN vm_algorithm_info_t b on b.algorithm_code = mm.algorithm_code and b.delete_flag = '0' WHERE ord.delete_flag = 0 AND ord.ord_status IN (0, 1, 2) AND b.app_scenarios = '1'
AND mm.channel_code in
#{labelIdItem}
AND ( (NOT EXISTS (SELECT 1 FROM vm_order_algorithm_config oac WHERE oac.order_code = ord.order_code AND oac.delete_flag = 0 AND oac.algorithm_type = 1) AND oral.delete_flag = 0 AND oral.ord_status IN (0, 1, 2)) OR EXISTS (SELECT 1 FROM vm_order_algorithm_config oac WHERE oac.order_code = ord.order_code AND oac.device_code = mm.device_code AND oac.algorithm_code = mm.algorithm_code AND oac.delete_flag = 0 AND oac.algorithm_type = 1) ) GROUP BY mm.device_code, mm.channel_code ORDER BY mm.device_code,mm.channel_code;

SELECT DISTINCT oral.algorithm_code, oral.algorithm_name
FROM vm_order_devices tt
LEFT JOIN vm_order_algorithms oral on oral.tenant_id = tt.tenant_id AND oral.order_code = tt.order_code
AND oral.package_code = tt.package_code
LEFT JOIN vm_channel_info_t chan ON tt.device_code = chan.device_code
LEFT JOIN vm_algorithm_info_t b on b.algorithm_code = oral.algorithm_code and b.delete_flag = '0'
WHERE tt.delete_flag = 0 AND tt.ord_status IN (0, 1, 2) AND tt.industry_code = #{industryCode}
AND oral.delete_flag = 0 AND oral.ord_status IN (0, 1, 2)
AND b.app_scenarios = '1'

    AND tt.device_code = #{deviceCode}


    AND chan.channel_code = #{channelCode}


    AND tt.tenant_id = #{tenantId}


    and oral.accept_node =#{platformCode}

AND (
    NOT EXISTS (SELECT 1 FROM vm_order_algorithm_config oac WHERE oac.order_code = tt.order_code AND oac.delete_flag = 0 AND oac.algorithm_type = 1)
    OR
    EXISTS (SELECT 1 FROM vm_order_algorithm_config oac WHERE oac.order_code = tt.order_code AND oac.device_code = tt.device_code AND oac.algorithm_code = oral.algorithm_code AND oac.delete_flag = 0 AND oac.algorithm_type = 1)
)
ORDER BY oral.algorithm_code

SELECT DISTINCT tt.algorithm_code, tt.algorithm_name FROM vm_algorithm_config tt LEFT JOIN vm_order_devices ord ON tt.device_code = ord.device_code AND tt.tenant_id = ord.tenant_id AND tt.industry_code = ord.industry_code LEFT JOIN vm_order_algorithms oral ON tt.algorithm_code = oral.algorithm_code AND tt.tenant_id = oral.tenant_id AND tt.industry_code = oral.industry_code AND oral.order_code = ord.order_code AND oral.package_code = ord.package_code LEFT JOIN vm_algorithm_info_t b on b.algorithm_code = tt.algorithm_code and b.delete_flag = '0' WHERE ord.delete_flag = 0 AND ord.ord_status IN (0, 1, 2) AND tt.delete_flag = 0 AND tt.industry_code = #{industryCode} AND tt.tenant_id = #{tenantId} AND b.app_scenarios = '1'
AND tt.device_code = #{deviceCode}
AND tt.channel_code = #{channelCode}
and oral.accept_node =#{platformCode}
AND ( (NOT EXISTS (SELECT 1 FROM vm_order_algorithm_config oac WHERE oac.order_code = ord.order_code AND oac.delete_flag = 0 AND oac.algorithm_type = 1) AND oral.delete_flag = 0 AND oral.ord_status IN (0, 1, 2)) OR EXISTS (SELECT 1 FROM vm_order_algorithm_config oac WHERE oac.order_code = ord.order_code AND oac.device_code = tt.device_code AND oac.algorithm_code = tt.algorithm_code AND oac.delete_flag = 0 AND oac.algorithm_type = 1) ) ORDER BY tt.algorithm_code

SELECT DISTINCT oral.algorithm_code, oral.algorithm_name
FROM vm_order_devices tt
LEFT JOIN vm_order_algorithms oral on oral.tenant_id = tt.tenant_id AND oral.order_code = tt.order_code
AND oral.package_code = tt.package_code
LEFT JOIN vm_channel_info_t chan ON tt.device_code = chan.device_code
LEFT JOIN vm_algorithm_info_t b on b.algorithm_code = oral.algorithm_code and b.delete_flag = '0'
WHERE tt.delete_flag = 0 AND tt.ord_status IN (0, 1, 2) AND tt.industry_code = #{industryCode}
AND oral.delete_flag = 0 AND oral.ord_status IN (0, 1, 2) AND tt.tenant_id = #{tenantId}
AND b.app_scenarios = '1'

    AND tt.device_code = #{deviceCode}


    AND chan.channel_code = #{channelCode}


    and oral.accept_node =#{platformCode}

AND oral.algorithm_code NOT IN (
SELECT DISTINCT tt.algorithm_code
FROM vm_algorithm_config tt
LEFT JOIN vm_order_devices ord ON tt.device_code = ord.device_code AND tt.tenant_id = ord.tenant_id
AND tt.industry_code = ord.industry_code
LEFT JOIN vm_order_algorithms oral ON tt.algorithm_code = oral.algorithm_code
AND tt.tenant_id = oral.tenant_id AND tt.industry_code = oral.industry_code
AND oral.order_code = ord.order_code AND oral.package_code = ord.package_code
LEFT JOIN vm_algorithm_info_t b on b.algorithm_code = oral.algorithm_code and b.delete_flag = '0'
WHERE ord.delete_flag = 0 AND ord.ord_status IN (0, 1, 2) AND oral.delete_flag = 0
AND oral.ord_status IN (0, 1, 2) AND tt.delete_flag = 0 AND tt.industry_code = #{industryCode}
AND tt.tenant_id = #{tenantId}
AND b.app_scenarios = '1'

    AND tt.device_code = #{deviceCode}


    AND tt.channel_code = #{channelCode}

)
AND (
    NOT EXISTS (SELECT 1 FROM vm_order_algorithm_config oac WHERE oac.order_code = tt.order_code AND oac.delete_flag = 0 AND oac.algorithm_type = 1)
    OR
    EXISTS (SELECT 1 FROM vm_order_algorithm_config oac WHERE oac.order_code = tt.order_code AND oac.device_code = tt.device_code AND oac.algorithm_code = oral.algorithm_code AND oac.delete_flag = 0 AND oac.algorithm_type = 1)
)
ORDER BY oral.algorithm_code

SELECT DISTINCT vi.config_id, vi.task_type, vi.status, vi.device_code, vi.channel_code
FROM (
SELECT config_id,device_code,channel_code,tenant_id,STATUS,'1' AS task_type
FROM vm_algorithm_config
WHERE delete_flag = 0 AND tenant_id = #{tenantId}

    AND config_id in

        #{labelIdItem}


UNION ALL
SELECT CONVERT( ID, CHAR ) AS config_id,device_code,channel_code,tenant_id,STATUS,'2' AS task_type
FROM vm_algorithm_give_config
WHERE delete_flag = 0 AND tenant_id = #{tenantId}

    AND CONVERT( ID, CHAR )  in

        #{labelIdItem}


) vi WHERE 1=1

    AND vi.device_code = #{deviceCode}


    AND vi.channel_code = #{channelCode}

