mapper.select:
WITH filtered_alg AS (
SELECT algorithm_code, order_code, tenant_id, industry_code, package_code
FROM vm_order_algorithms
WHERE delete_flag = '0'

    and tenant_id =#{tenantId}


    and industry_code =#{industryCode}


    and accept_node =#{platformCode}


    and algorithm_name LIKE CONCAT('%',#{algorithmName},'%')

)
SELECT DISTINCT
fa.algorithm_code,
b.algorithm_name,
b.algorithm_shape,
CONVERT(b.extend_json, CHAR) AS extend_json,
b.analy_type,
b.algorithm_model_type
FROM filtered_alg fa
INNER JOIN vm_algorithm_info_t b ON b.algorithm_code = fa.algorithm_code AND b.delete_flag = '0' AND b.app_scenarios = '1'
INNER JOIN vm_order_customer voc ON fa.order_code = voc.order_code AND voc.delete_flag = '0' AND voc.ord_status IN (0,1,2)
INNER JOIN vm_order_devices e ON fa.order_code = e.order_code AND fa.tenant_id = e.tenant_id AND fa.industry_code = e.industry_code AND e.package_code = fa.package_code
AND e.delete_flag = '0'

    AND e.tenant_id = #{tenantId}


    AND e.industry_code = #{industryCode}


    AND e.accept_node = #{platformCode}


    and e.device_code =#{deviceCode}

AND (
    NOT EXISTS (SELECT 1 FROM vm_order_algorithm_config oac WHERE oac.order_code = e.order_code AND oac.delete_flag = 0 AND oac.algorithm_type = 1)
    OR
    EXISTS (SELECT 1 FROM vm_order_algorithm_config oac WHERE oac.order_code = e.order_code AND oac.device_code = e.device_code AND oac.algorithm_code = fa.algorithm_code AND oac.delete_flag = 0 AND oac.algorithm_type = 1)
)

select distinct e.device_code,a.algorithm_code,b.algorithm_name,b.algorithm_shape,CONVERT(b.extend_json, CHAR) as extendJson, b.analy_type from vm_order_algorithms a inner join vm_algorithm_info_t b on b.algorithm_code = a.algorithm_code and b.delete_flag = '0' left join vm_order_devices e on e.order_code = a.order_code and e.tenant_id = a.tenant_id and e.industry_code = a.industry_code and a.package_code = e.package_code and e.delete_flag = '0' left join vm_order_customer voc on a.order_code = voc.order_code and voc.delete_flag = '0' where a.delete_flag = '0' and voc.ord_status in (0,1,2) AND b.app_scenarios = '1'
and a.tenant_id =#{tenantId}
and a.industry_code =#{industryCode}
and a.accept_node =#{platformCode}
